$('surfaceRows').addEventListener('change',e=>{if(e.target.dataset.objectDistance){specChange('objectDistance',e.target.value);return}const key=e.target.dataset.key;if(!key)return;const s=surfaces.find(s=>s.id===Number(e.target.closest('tr').dataset.id));if(key==='stop'){if(!e.target.checked){e.target.checked=s.stop;return}surfaces.forEach(surface=>surface.stop=false);s.stop=true}else if(key==='semiAuto'){const index=surfaces.indexOf(s),[first,last]=elementRanges().find(([first,last])=>index>=first&&index<=last);for(let i=first;i<=last;i++){if(!e.target.checked)surfaces[i].semi=semiDiameter(surfaces[i]);surfaces[i].semiAuto=e.target.checked}}else if(key==='type'){s.type=e.target.value;if(s.type==='Asphere'){s.conic??=0;s.asphere??={4:0}}}else if(key==='conic')s.conic=Number(e.target.value);else if(key==='asphere')s.asphere[e.target.dataset.order]=Number(e.target.value);else if(key==='paraxialSolve')s.paraxialSolve=e.target.checked;else if(key==='thickness'&&s.type==='Image'&&surfaces.indexOf(s)>0)surfaces[surfaces.indexOf(s)-1].defocus=Number(e.target.value);else s[key]=['radius','thickness','semi','group'].includes(key)?Number(e.target.value):e.target.value;renderTable();renderGroups();drawLayout();drawCurves()});
$('surfaceRows').addEventListener('click',e=>{const add=e.target.closest('[data-add-asphere]');if(add){const s=surfaces.find(s=>s.id===Number(add.dataset.addAsphere)),order=Math.max(4,...Object.keys(s.asphere).map(Number))+2;s.asphere[order]=0;renderTable();return}const reduce=e.target.closest('[data-reduce-asphere]');if(reduce){const s=surfaces.find(s=>s.id===Number(reduce.dataset.reduceAsphere)),order=Math.max(4,...Object.keys(s.asphere).map(Number));if(order>4){delete s.asphere[order];renderTable();drawLayout()}return}const insert=e.target.closest('[data-insert]');if(insert){const index=surfaces.findIndex(s=>s.id===Number(insert.dataset.insert));if(index<0)return;surfaces.splice(index,0,{id:nextSurface++,type:'Sphere',stop:!surfaces.some(surface=>surface.stop),radius:0,thickness:0,material:index>0?surfaces[index-1].material:'AIR',semi:10,semiAuto:true,group:surfaces[index].group});renderAll();return}if(e.target.closest('input,select,label,.asphere-editor'))return;const del=e.target.closest('[data-delete]');if(del){const index=surfaces.findIndex(s=>s.id===Number(del.dataset.delete));if(index<0||surfaces[index].type==='Image')return;if(index>0&&index<surfaces.length-1)surfaces[index-1].thickness+=surfaces[index].thickness;surfaces.splice(index,1);if(!surfaces.some(surface=>surface.stop)){const stop=surfaces.find(surface=>surface.type!=='Image');if(stop)stop.stop=true}if(selected===Number(del.dataset.delete))selected=null;renderAll();return}const tr=e.target.closest('tr');if(tr&&tr.dataset.id)selectSurface(selected===Number(tr.dataset.id)?null:Number(tr.dataset.id))});
