function renderGroups(){
$('legend').innerHTML=[{id:0,name:'Fixed'},...groups].map(g=>`<span><i class="dot" style="background:${color(g.id)}"></i>${esc(g.name)}</span>`).join('');
$('groupRows').innerHTML=groups.map(g=>`<div class="group" data-group="${g.id}"><div class="group-title"><span class="swatch" style="background:${color(g.id)}"></span><input class="group-name" data-field="name" value="${esc(g.name)}" aria-label="Group ${g.id} name"><button class="delete" data-remove-group="${g.id}" aria-label="Remove group ${g.id}">×</button></div><div class="group-meta"><span>${surfaces.filter(s=>s.group===g.id).length} surfaces</span><span class="group-position">Δz ${fmt(displacement(g.id,zoom))} mm</span></div><div class="curve-editor"><label>Coefficients a₀, a₁, a₂, … (mm)</label><input class="curve-input" data-field="polynomial" value="${parsePolynomial(g.polynomial).map(fmt).join(', ')}" aria-label="Group ${g.id} motion curve"><div class="sub" data-error style="color:#a84031"></div></div></div>`).join('');
$('curveHelp').innerHTML='Polynomial: Δz(t) = a₀ + a₁t + a₂t² + …<br>Displacements are relative to the baseline lens data. The image plane can be fixed or assigned to any group.';
}
function updateGroupPositions(){document.querySelectorAll('[data-group]').forEach(el=>el.querySelector('.group-position').textContent=`Δz ${fmt(displacement(Number(el.dataset.group),zoom))} mm`)}
function plotLimits(id,limits,redraw){const plot=$(id);plot.redrawPlot=redraw;plot.plotZoom??={scale:1,x:.5,y:.5};const {scale,x,y}=plot.plotZoom,dx=(limits.xmax-limits.xmin)/scale,dy=(limits.ymax-limits.ymin)/scale,cx=limits.xmin+x*(limits.xmax-limits.xmin),cy=limits.ymax-y*(limits.ymax-limits.ymin);return {...limits,xmin:cx-dx/2,xmax:cx+dx/2,ymin:cy-dy/2,ymax:cy+dy/2}}
