$('groupRows').addEventListener('change',e=>{const field=e.target.dataset.field;if(!field)return;const g=groups.find(g=>g.id===Number(e.target.closest('[data-group]').dataset.group));try{if(field==='polynomial')parsePolynomial(e.target.value);g[field]=e.target.value;renderAll()}catch(error){e.target.closest('.group').querySelector('[data-error]').textContent=error.message}});
$('groupRows').addEventListener('click',e=>{const button=e.target.closest('[data-remove-group]');if(!button)return;const id=Number(button.dataset.removeGroup);groups=groups.filter(g=>g.id!==id);surfaces.forEach(s=>{if(s.group===id)s.group=0});renderAll()});
