const lensCacheKey='ZoomLens.currentDesign';
function cacheLens(){try{localStorage.setItem(lensCacheKey,JSON.stringify(lensDocument()))}catch{}}
document.addEventListener('change',cacheLens);document.addEventListener('input',cacheLens);document.addEventListener('click',cacheLens);
const savedLensesKey='ZoomLens.savedLenses';
function savedLenses(){return JSON.parse(localStorage.getItem(savedLensesKey)||'[]')}
function renderSavedLenses(){const lenses=savedLenses();$('savedLensRows').innerHTML=lenses.map((lens,i)=>`<tr><td>${esc(lens.name)}</td><td><div class="lens-library-actions"><button class="btn" data-saved-lens="${i}" data-action="load">Load</button><button class="btn" data-saved-lens="${i}" data-action="rename">Rename</button><button class="btn" data-saved-lens="${i}" data-action="delete">Delete</button></div></td></tr>`).join('')+`<tr><td>PNP example</td><td><div class="lens-library-actions"><button class="btn" data-saved-lens="pnp" data-action="load">Load</button></div></td></tr>`;$('lensLibraryStatus').textContent=''}
let namingLensIndex=null,replaceLensName='';
function openLensName(index=null,name='zoom-lens'){namingLensIndex=index;replaceLensName='';$('lensNameTitle').textContent=index===null?'Save lens':'Rename lens';$('submitLensName').textContent=index===null?'Save':'Rename';$('lensNameInput').value=name;$('lensNameStatus').textContent='';$('lensNameDialog').showModal();$('lensNameInput').focus();$('lensNameInput').select()}
$('newLens').addEventListener('click',()=>{loadLensDocument(JSON.parse(newLensDocument));$('lensFileStatus').textContent=''});
$('saveLens').addEventListener('click',()=>openLensName());
$('cancelLensName').addEventListener('click',()=>$('lensNameDialog').close());
$('lensNameForm').addEventListener('submit',e=>{e.preventDefault();const name=$('lensNameInput').value.trim();if(!name)return;try{const lenses=savedLenses(),index=lenses.findIndex(lens=>lens.name===name);if(namingLensIndex!==null){if(index>=0&&index!==namingLensIndex){$('lensNameStatus').textContent='A lens with that name already exists.';return}lenses[namingLensIndex].name=name}else{if(index>=0&&replaceLensName!==name){replaceLensName=name;$('lensNameStatus').textContent='A lens with that name already exists. Replace it?';$('submitLensName').textContent='Replace';return}const entry={name,document:lensDocument()};if(index<0)lenses.push(entry);else lenses[index]=entry}localStorage.setItem(savedLensesKey,JSON.stringify(lenses));$('lensNameDialog').close();if($('lensLibrary').open)renderSavedLenses();$('lensFileStatus').textContent=`${namingLensIndex===null?'Saved':'Renamed'} "${name}".`}catch(error){$('lensNameStatus').textContent=error.message}});
$('loadLens').addEventListener('click',()=>{try{renderSavedLenses();$('lensLibrary').showModal()}catch(error){$('lensFileStatus').textContent=`Load failed: ${error.message}`}});
$('closeLensLibrary').addEventListener('click',()=>$('lensLibrary').close());
$('savedLensRows').addEventListener('click',e=>{const button=e.target.closest('[data-saved-lens]');if(!button)return;try{if(button.dataset.savedLens==='pnp'){if(button.dataset.action==='load'){loadLensDocument(JSON.parse(JSON.stringify(pnpExample)));$('lensFileStatus').textContent='Loaded PNP example.';$('lensLibrary').close()}return}const lenses=savedLenses(),index=Number(button.dataset.savedLens),lens=lenses[index];if(button.dataset.action==='load'){loadLensDocument(lens.document);$('lensFileStatus').textContent=`Loaded "${lens.name}".`;$('lensLibrary').close();return}if(button.dataset.action==='rename'){openLensName(index,lens.name);return}if(button.dataset.action==='delete')lenses.splice(index,1);localStorage.setItem(savedLensesKey,JSON.stringify(lenses));renderSavedLenses()}catch(error){$('lensLibraryStatus').textContent=error.message}});
$('saveLensDevice').addEventListener('click',async()=>{try{const text=JSON.stringify(lensDocument(),null,2);if(window.showSaveFilePicker){const handle=await window.showSaveFilePicker({suggestedName:'zoom-lens.json',types:[{description:'ZoomLens JSON',accept:{'application/json':['.json']}}]}),writer=await handle.createWritable();await writer.write(text);await writer.close()}else{const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='zoom-lens.json';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('lensFileStatus').textContent=''}catch(error){if(error.name!=='AbortError')$('lensFileStatus').textContent=`Save failed: ${error.message}`}});
$('loadLensDevice').addEventListener('click',()=>$('loadLensFile').click());
$('loadLensFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text();if(/\.seq$/i.test(file.name)){const imported=readSequence(text);loadLensDocument(imported.document);$('lensFileStatus').textContent=imported.notes.join(' ')}else{loadLensDocument(JSON.parse(text));$('lensFileStatus').textContent=''}}catch(error){$('lensFileStatus').textContent=`Load failed: ${error.message}`}finally{e.target.value=''}});

function performanceChart(id,series,xLabel,yLabel,limits={},pointsOnly=false){const W=600,H=pointsOnly?420:310,L=105,R=24,T=18,B=60,finite=series.flatMap(s=>s.points).filter(p=>p.every(Number.isFinite));$(id).setAttribute('viewBox',`0 0 ${W} ${H}`);if(!finite.length){setPlotCoordinates(id,null);$(id).innerHTML=svg('text',{x:W/2,y:H/2,'text-anchor':'middle','font-size':12,fill:'#7b8d92'},'No finite data');return}let xmin=limits.xmin??Math.min(...finite.map(p=>p[0])),xmax=limits.xmax??Math.max(...finite.map(p=>p[0])),ymin=limits.ymin??Math.min(0,...finite.map(p=>p[1])),ymax=limits.ymax??Math.max(0,...finite.map(p=>p[1]));if(xmax-xmin<1e-10){xmin-=.5;xmax+=.5}if(ymax-ymin<1e-10){ymin-=.5;ymax+=.5}if(limits.ymin===undefined&&limits.ymax===undefined){const span=ymax-ymin;ymin-=span*.1;ymax+=span*.1}if(pointsOnly){const radius=Math.max(Math.abs(ymin),Math.abs(ymax),Math.abs(xmin)*(H-T-B)/(W-L-R),Math.abs(xmax)*(H-T-B)/(W-L-R));ymin=-radius;ymax=radius;xmin=-radius*(W-L-R)/(H-T-B);xmax=-xmin}({xmin,xmax,ymin,ymax}=plotLimits(id,{xmin,xmax,ymin,ymax},()=>performanceChart(id,series,xLabel,yLabel,limits,pointsOnly)));const x=v=>L+(v-xmin)/(xmax-xmin)*(W-L-R),y=v=>H-B-(v-ymin)/(ymax-ymin)*(H-T-B);let out='';for(let i=0;i<=4;i++){const xv=xmin+(xmax-xmin)*i/4,yv=ymin+(ymax-ymin)*i/4;out+=svg('line',{x1:x(xv),x2:x(xv),y1:T,y2:H-B,stroke:'#e3eaeb'})+svg('text',{x:x(xv),y:H-B+18,'text-anchor':'middle','font-size':12,fill:'#7b8d92'},fmt(xv))+svg('line',{x1:L,x2:W-R,y1:y(yv),y2:y(yv),stroke:'#e3eaeb'})+svg('text',{x:L-8,y:y(yv)+3,'text-anchor':'end','font-size':12,fill:'#7b8d92'},fmt(yv))}if(ymin<0&&ymax>0)out+=svg('line',{x1:L,x2:W-R,y1:y(0),y2:y(0),stroke:'#acbfc3'});out+=plotClip(id,W,H,L,R,T,B);for(const line of series){if(pointsOnly){for(const p of line.points)if(p.every(Number.isFinite))out+=svg('circle',{cx:x(p[0]),cy:y(p[1]),r:1.5,fill:line.color,'fill-opacity':'.65'});continue}let path='',connected=false;for(const p of line.points){if(!p.every(Number.isFinite)){connected=false;continue}path+=`${connected?'L':'M'}${x(p[0])},${y(p[1])} `;connected=true}out+=svg('path',{d:path,fill:'none',stroke:line.color,'stroke-width':1.5,'stroke-dasharray':line.dashed?'5 3':''})}out+='</g>';out+=svg('text',{x:(L+W-R)/2,y:H-7,'text-anchor':'middle','font-size':14,fill:'#6c7e84'},esc(xLabel))+svg('text',{transform:`translate(14 ${(T+H-B)/2}) rotate(-90)`,'text-anchor':'middle','font-size':14,fill:'#6c7e84'},esc(yLabel));$(id).innerHTML=out;setPlotCoordinates(id,{W,H,L,R,T,B,xmin,xmax,ymin,ymax,xUnit:xLabel.match(/\(([^)]+)\)/)?.[1]||'',yUnit:yLabel.match(/\(([^)]+)\)/)?.[1]||''})}
let performanceKey='',performanceData=null,performanceRun=0;
const performanceStages=['coefficients','fans','field','spot','mtf'],performanceViews={coefficients:['thirdOrderTable'],fans:['fanTView','fanSView'],field:['fieldCurvaturePlotView','distortionPlotView'],spot:['spotPlotView'],mtf:['mtfPlotView']};
function performanceLoading(stage,loading){$(stage+'Loading').hidden=!loading;for(const id of performanceViews[stage])$(id).hidden=loading;if(stage==='mtf'){ $('mtfMaximum').disabled=loading;$('mtfStep').disabled=loading}}
function performanceWavelengthLegend(){return specs.wavelengths.map((value,i)=>`<span><i class="dot" style="background:${wavelengthColor(i)}"></i>${fmt(value)} nm</span>`).join('')}
function performanceFieldLabel(value){return `${fmt(value)} ${specs.fieldType==='imageHeight'?'mm image':specs.conjugate==='finite'?'mm object':'°'}`}
function renderPerformanceMTF(){const data=performanceData;if(!data)return;const cutoffs=data.cutoffs,maximum=$('mtfMaximum').value.trim()?Number($('mtfMaximum').value):Math.max(0,...cutoffs),step=$('mtfStep').value.trim()?Number($('mtfStep').value):maximum/100;if(!(cutoffs.length&&maximum>0&&step>0&&Number.isFinite(maximum)&&Number.isFinite(step))){$('mtfStatus').textContent='MTF requires a finite image-space NA and positive maximum frequency and frequency step.';performanceChart('mtfPlot',[],'Spatial frequency (cycles/mm)','MTF');return}if(maximum/step>4096){$('mtfStatus').textContent='Increase the frequency step to use at most 4,096 intervals.';return}$('mtfStatus').textContent='';const frequencies=Array.from({length:Math.floor(maximum/step)+1},(_,i)=>i*step);if(frequencies.at(-1)<maximum)frequencies.push(maximum);const series=[];for(let f=0;f<data.fields.length;f++){const field=data.fields[f],waves=field.waves.filter(wave=>wave.cutoff>0&&wave.T.length&&wave.S.length);if(!waves.length)continue;for(const axis of ['T','S'])series.push({color:fieldColors[f%fieldColors.length],dashed:axis==='S',points:frequencies.map(frequency=>{let re=0,im=0;for(const wave of waves){const value=interpolateOTF(wave[axis],frequency/(wave['cutoff'+axis]??wave.cutoff));re+=value[0];im+=value[1]}return [frequency,Math.hypot(re,im)/waves.length]})})}const axialCutoffs=data.cutoffs;series.push({color:'#172b32',dashed:true,points:frequencies.map(frequency=>[frequency,axialCutoffs.length?axialCutoffs.reduce((sum,cutoff)=>sum+diffractionMTF(frequency/cutoff),0)/axialCutoffs.length:0])});performanceChart('mtfPlot',series,'Spatial frequency (cycles/mm)','MTF',{xmin:0,xmax:maximum,ymin:0,ymax:1});$('mtfLegend').innerHTML='<span><i class="dot" style="background:#172b32"></i>Diffraction limit</span>'+data.fields.map((field,i)=>`<span><i class="dot" style="background:${fieldColors[i%fieldColors.length]}"></i>Field ${i+1} · ${performanceFieldLabel(field.value)}</span>`).join('')+'<span>Solid: Tangential · Dashed: Sagittal</span>'}
function renderPerformanceFans(){const waves=(performanceData?.fields[Number($('aberrationField').value)||0]?.waves||[]).filter(wave=>wave.waveIndex===specs.referenceWavelengthIndex);performanceChart('fanT',waves.map(wave=>({color:wave.color,points:wave.fanT})),'Tangential normalized pupil','Tangential ray error (µm)',{xmin:-1,xmax:1});performanceChart('fanS',waves.map(wave=>({color:wave.color,points:wave.fanS})),'Sagittal normalized pupil','Sagittal ray error (µm)',{xmin:-1,xmax:1})}
function renderPerformanceSpot(){const spot=performanceData?.spots[Number($('spotField').value)||0];if(!spot){performanceChart('spotPlot',[],'Sagittal x (µm)','Tangential y (µm)');return}const points=spot.waves.flatMap(wave=>wave.points);if(!points.length){performanceChart('spotPlot',[],'Sagittal x (µm)','Tangential y (µm)');return}const radius=Math.max(.1,...points.flatMap(p=>p.map(Math.abs)))*1.15;performanceChart('spotPlot',spot.waves,'Sagittal x (µm)','Tangential y (µm)',{xmin:-radius,xmax:radius,ymin:-radius,ymax:radius},true)}
function renderPerformanceStage(stage){const data=performanceData;if(stage==='coefficients'){const cell=value=>Number.isNaN(value)?'—':Number.isFinite(value)?fmt(value):`${value<0?'−':''}∞`,values=row=>row.map(value=>`<td class="units">${cell(value)}</td>`).join('');$('thirdOrderData').innerHTML=data.thirdOrder.map(report=>`${report.rows.map(row=>`<tr><td class="units">${row.label}</td>${values(row.values)}</tr>${row.aspheric?`<tr><td></td>${row.aspheric.slice(0,6).map((value,i)=>`<td class="units">${i===4?'':cell(value)}</td>`).join('')}<td colspan="3" class="units">ASPHERIC CONTRIBUTIONS</td></tr>`:''}`).join('')}<tr><th>SUM</th>${values(report.sum)}</tr>`).join('');$('thirdOrderField').textContent=`Maximum field ${performanceFieldLabel(Math.max(...specs.fields.map(Math.abs)))}. Transverse aberrations in mm; PTZ in mm⁻¹. AX/LAT: last minus first listed wavelength.`;}else if(stage==='fans'){const selectedField=$('aberrationField').value;$('aberrationField').innerHTML=data.fields.map((field,i)=>`<option value="${i}" ${String(i)===selectedField?'selected':''}>${field.value===0?'On axis':performanceFieldLabel(field.value)}</option>`).join('');renderPerformanceFans();}else if(stage==='field'){performanceChart('fieldCurvaturePlot',data.curvature.map(curve=>({...curve,points:curve.points.map(([field,shift])=>[shift,field])})),'Focus shift from image plane (mm)',`Field (${specs.fieldType==='imageHeight'?'mm image':specs.conjugate==='finite'?'mm object':'degrees'})`,{ymin:0,ymax:Math.max(...specs.fields.map(Math.abs))||1});performanceChart('distortionPlot',data.distortion,`Field (${specs.fieldType==='imageHeight'?'mm image':specs.conjugate==='finite'?'mm object':'degrees'})`,'Distortion (%)');}else if(stage==='spot'){const selectedValue=$('spotField').value;$('spotField').innerHTML=data.spots.map((spot,i)=>`<option value="${i}" ${String(i)===selectedValue?'selected':''}>${spot.value===0?'On axis':performanceFieldLabel(spot.value)}</option>`).join('');renderPerformanceSpot();$('spotWavelengthLegend').innerHTML=performanceWavelengthLegend()}else if(stage==='mtf')renderPerformanceMTF();$('performanceStatus').textContent=[...data.messages].join(' ');performanceLoading(stage,false)}
$('mtfMaximum').addEventListener('change',renderPerformanceMTF);$('mtfStep').addEventListener('change',renderPerformanceMTF);$('spotField').addEventListener('change',renderPerformanceSpot);$('aberrationField').addEventListener('change',renderPerformanceFans);


function renderFirstOrder(rows){const value=n=>Number.isNaN(n)?'—':Number.isFinite(n)?fmt(n):`${n<0?'−':''}∞`;$('firstOrderData').innerHTML=rows?rows.map(([name,n,unit])=>`<tr><td>${name}</td><td class="units" style="text-align:right;padding-right:20px">${value(n)}${Number.isFinite(n)&&unit?' '+unit:''}</td></tr>`).join(''):'<tr><td colspan="2">First-order data unavailable for the current layout.</td></tr>'}
function loadLensDocument(data){setLensDocument(data);layoutResult=null;selected=null;nextSurface=Math.max(0,...surfaces.map(s=>s.id))+1;nextGroup=Math.max(0,...groups.map(g=>g.id))+1;nextMaterial=Math.max(0,...customMaterials.map(m=>m.id))+1;for(const key of ['conjugate','objectDistance','apertureMode','fieldType'])$(key).value=specs[key];renderApertureInput();renderWavelengths();$('specStatus').textContent='';$('materialStatus').textContent='';renderMaterials();renderFieldLegend();renderAll();updateZoom(zoom);cacheLens()}
let layoutResult=null,layoutAnalysis=null,layoutController=null,layoutTimer=null,layoutRun=0,performanceController=null;
function requestLayout(){const run=++layoutRun;clearTimeout(layoutTimer);layoutController?.abort();layoutTimer=setTimeout(async()=>{const controller=new AbortController();layoutController=controller;const analysis=layoutAnalysis?.key===envelopeInputKey()?layoutAnalysis.data:null;try{const response=await fetch('/api/layout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document:lensDocument(),stream:true,current_only:!!analysis},encodeNumber),signal:controller.signal});if(!response.ok)throw Error((await response.json()).detail||'Layout calculation failed.');const reader=response.body.getReader(),decoder=new TextDecoder();let pending='';while(true){const {value,done}=await reader.read();pending+=decoder.decode(value??new Uint8Array(),{stream:!done});const records=pending.split('\n');pending=records.pop();for(const record of records){if(!record.trim())continue;if(run!==layoutRun){await reader.cancel();return}const next=JSON.parse(record,decodeNumber);if(next.error)throw Error(next.error);let data=next.data;if(analysis){data={...data,envelope:analysis.envelope,autoSemis:analysis.autoSemis,autoClearSemis:analysis.autoClearSemis,focus:[...analysis.focus.filter(([t])=>t!==zoom),...data.focus].sort((a,b)=>a[0]-b[0]),zoomOptics:[...analysis.zoomOptics.filter(row=>row.position!==zoom),...data.zoomOptics].sort((a,b)=>a.position-b.position)}}Object.assign(specs,data.aperture);surfaces.forEach((s,i)=>s.semiAuto=data.semiAuto[i]);autoSemis.clear();autoClearSemis.clear();for(const [id,value] of data.autoSemis)autoSemis.set(id,value);for(const [id,value] of data.autoClearSemis)autoClearSemis.set(id,value);autoVignettingValues.clear();for(const [value,factors] of data.vignetting)autoVignettingValues.set(value,factors);zoomEnvelope=data.envelope;layoutResult={...data,key:JSON.stringify(lensDocument(),encodeNumber)};if(next.stage==='complete')layoutAnalysis={key:envelopeInputKey(),data};renderApertureInput();updateCoordinates();drawLayout(true);if(next.stage==='current'&&!analysis)$('geometryStatus').textContent=[$('geometryStatus').textContent,'Updating full-zoom apertures and curves…'].filter(Boolean).join(' ');cacheLens()}if(done)break}}catch(error){if(error.name!=='AbortError'&&run===layoutRun)$('geometryStatus').textContent=error.message}finally{if(layoutController===controller)layoutController=null}},60)}
async function renderPerformance(){const run=++performanceRun;performanceController?.abort();const controller=new AbortController();performanceController=controller;try{const key=JSON.stringify(lensDocument(),encodeNumber);if(key===performanceKey&&performanceData){for(const stage of performanceStages)renderPerformanceStage(stage);return}performanceKey='';$('performanceStatus').textContent='';for(const stage of performanceStages)performanceLoading(stage,true);$('aberrationField').disabled=true;$('spotField').disabled=true;const response=await fetch('/api/performance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document:lensDocument()},encodeNumber),signal:controller.signal});if(!response.ok)throw Error((await response.json()).detail||'Performance calculation failed.');const reader=response.body.getReader(),decoder=new TextDecoder();let pending='',completed=false;while(true){const {value,done}=await reader.read();pending+=decoder.decode(value??new Uint8Array(),{stream:!done});const records=pending.split('\n');pending=records.pop();for(const record of records){if(!record.trim())continue;if(run!==performanceRun){await reader.cancel();return}const next=JSON.parse(record,decodeNumber);if(next.error)throw Error(next.error);performanceData=next.data;renderPerformanceStage(next.stage);if(next.stage==='mtf')completed=true;if(next.stage==='fans')$('aberrationField').disabled=false;if(next.stage==='spot')$('spotField').disabled=false}if(done)break}if(!completed)throw Error('Performance response ended before all plots were calculated.');if(run===performanceRun)performanceKey=key;cacheLens()}catch(error){if(error.name==='AbortError'||run!==performanceRun)return;$('performanceStatus').textContent=error.message;for(const stage of performanceStages)performanceLoading(stage,false);$('aberrationField').disabled=false;$('spotField').disabled=false}finally{if(performanceController===controller)performanceController=null}}

renderWavelengths();
const workspaceTabs=['design','specification','performance','zoom','materials'];
for(const tab of workspaceTabs)$(tab+'TabButton').addEventListener('click',()=>{for(const name of workspaceTabs){$(name+'Tab').hidden=name!==tab;$(name+'TabButton').setAttribute('aria-selected',String(name===tab))}if(tab==='design'||tab==='zoom'){ $(tab==='zoom'?'zoomDrawingSlot':'designDrawingSlot').appendChild($('lensDrawingPanel'));drawingPointer=null;updateDrawingCoordinates();drawLayout()}if(tab==='performance')renderPerformance();else{performanceRun++;performanceController?.abort()}});
let restoredLens=false;try{const cached=localStorage.getItem(lensCacheKey);if(cached){loadLensDocument(JSON.parse(cached));restoredLens=true}}catch{}
if(!restoredLens){renderMaterials();renderFieldLegend();renderAll()}

function zoomChartMarkers(id){const axes=$(id).coordinateAxes;if(!axes)return;const {W,H,L,R,T,B,xmin,xmax}=axes,x=t=>L+(t-xmin)/(xmax-xmin)*(W-L-R);$(id).innerHTML+=svg('g',{'clip-path':`url(#${id}Clip)`},svg('line',{x1:x(0),x2:x(0),y1:T,y2:H-B,stroke:'#829399','stroke-dasharray':'2 4'})+svg('line',{x1:x(zoom),x2:x(zoom),y1:T,y2:H-B,stroke:'#007d78','stroke-dasharray':'5 4'}))}
function drawZoomOptics(){const samples=layoutResult?.zoomOptics??[],na=specs.apertureMode==='na',label=na?'Image-space NA':'F/#',display=n=>Number.isNaN(n)||n===undefined?'—':Number.isFinite(n)?fmt(n):`${n<0?'−':''}∞`;$('zoomEfl').textContent=display(layoutResult?.firstOrder?.[0]?.[1]);$('zoomApertureLabel').textContent=label;$('zoomAperture').textContent=display(layoutResult?.aperture?.[na?'na':'fnumber']);const finite=samples.map(row=>row.efl).filter(Number.isFinite);$('zoomEflRange').textContent=finite.length?`EFL range ${fmt(Math.min(...finite))} – ${fmt(Math.max(...finite))} mm`:'';for(const [id,key,title,color] of [['eflPlot','efl','EFL (mm)','#007d78'],['zoomAperturePlot','aperture',label,'#c96928']]){const values=samples.map(row=>row[key]).filter(Number.isFinite),min=Math.min(...values),max=Math.max(...values),pad=(max-min||Math.abs(max)||1)*.1;performanceChart(id,[{color,points:samples.map(row=>[row.position,row[key]])}],'Zoom coordinate',title,{xmin:-1,xmax:1,...values.length?{ymin:min-pad,ymax:max+pad}:{}});$(id).redrawPlot=drawZoomOptics;zoomChartMarkers(id)}}
